namespace DynamicNotch.Services;

/// <summary>
/// The notch's languages: English (the source), French and Arabic. A text is looked up by its English wording;
/// anything without a translation stays English. Arabic reads right to left (see <see cref="Rtl"/>).
/// </summary>
public static class Loc
{
    public static string Lang { get; private set; } = "en";
    public static bool Rtl => Lang == "ar";

    public static void Set(string lang) => Lang = lang is "fr" or "ar" ? lang : "en";

    public static string T(string en) => Lang switch
    {
        "fr" => Fr.TryGetValue(en, out var f) ? f : en,
        "ar" => Ar.TryGetValue(en, out var a) ? a : en,
        _ => en,
    };

